body.query:
{ markets(first: 30, orderBy: SupplyAssetsUsd, orderDirection: Desc,
    where: {chainId_in: [1], listed: true, isIdle: false}) {
  items {
    marketId lltv listed irmAddress
    loanAsset { symbol decimals address }
    collateralAsset { symbol decimals address }
    oracle { address type }
    warnings { type level }
    state {
      blockNumber timestamp price supplyAssets borrowAssets borrowShares
      supplyAssetsUsd borrowAssetsUsd liquidityAssetsUsd utilization
      supplyApy borrowApy
    }
  }
} }

{ markets(first: 30, orderBy: SupplyAssetsUsd, orderDirection: Desc,
    where: {chainId_in: [1], listed: true, isIdle: false}) {
  items {
    marketId state { price timestamp blockNumber }
    oracle {
      address type data {
        ... on MorphoChainlinkOracleV2Data {
          scaleFactor
          baseFeedOne { address decimals } baseFeedTwo { address decimals }
          quoteFeedOne { address decimals } quoteFeedTwo { address decimals }
          baseOracleVault { address } quoteOracleVault { address }
        }
        ... on MorphoChainlinkOracleData {
          scaleFactor
          baseFeedOne { address decimals } baseFeedTwo { address decimals }
          quoteFeedOne { address decimals } quoteFeedTwo { address decimals }
          baseOracleVault { address }
        }
      }
    }
  }
} }

query Positions($ids: [String!], $skip: Int) {
  marketPositions(first: 100, skip: $skip, orderBy: BorrowShares, orderDirection: Desc,
    where: {chainId_in: [1], marketUniqueKey_in: $ids, borrowShares_gte: 1}) {
    items {
      id healthFactor
      market { marketId }
      state { timestamp collateral borrowShares borrowAssets borrowAssetsUsd }
    }
  }
}

